-- Help search without client API (helpsearch.lua uses it; helpcore_test.lua tests it with the real data). Offline: no
-- server and no AI call. The player types a question or a few words ("how do I get orbs", "gems", "como subir de nivel")
-- and gets the best answers of three sources:
--   card    the "How it works" cards (HowData of game_howitworks), English and pt-BR, plus the card's keywords, level and
--           top menu path (HelpSearchData.cards, generated by server/tools/gen_guide_data.lua) and its unlock entries
--   unlock  an unlock entry of the top menu with no card (HelpSearchData.unlocks; every entry has a card today)
--   codex   the Codex entries (CodexData of game_codex): name, tab, summary line and the first paragraphs, English only
-- Ranking: each word of the query is folded (lower case, accents off, so "nivel" finds "nível"), plurals cut ("orbs",
-- "masmorras", "níveis"), small words dropped ("how", "do", "como", "de"), then looked up in the title (10), the keywords
-- and tab (6) and the text (2); a word that starts a longer word counts less, a synonym (SYNONYMS, en and pt) 0.7 of it.
-- A result that holds every word scores more; a title that holds every word more again; cards come before the Codex.
-- Texts: pt in the data is UTF-8; the query from the client's text box is cp1252. fold() reads both.
-- Lua 5.1 / LuaJIT and Lua 5.3 compatible.

HelpCore = {}
local C = HelpCore

C.WEIGHT = { title = 10, tag = 6, body = 2, prefix = 0.6, synonym = 0.7, allInTitle = 4 }
C.KIND = { card = 1.0, unlock = 0.95, codex = 0.85 }
C.LIMIT = 8
C.SNIPPET = 80

-- ---------------------------------------------------------------- folding
-- Latin-1 code points 0xC0..0xFF -> ASCII (the same for UTF-8 C3 xx and a single cp1252 byte)
local LATIN = {}
do
  local map = {
    a = { 0xE0, 0xE1, 0xE2, 0xE3, 0xE4, 0xE5, 0xC0, 0xC1, 0xC2, 0xC3, 0xC4, 0xC5 },
    e = { 0xE8, 0xE9, 0xEA, 0xEB, 0xC8, 0xC9, 0xCA, 0xCB },
    i = { 0xEC, 0xED, 0xEE, 0xEF, 0xCC, 0xCD, 0xCE, 0xCF },
    o = { 0xF2, 0xF3, 0xF4, 0xF5, 0xF6, 0xD2, 0xD3, 0xD4, 0xD5, 0xD6 },
    u = { 0xF9, 0xFA, 0xFB, 0xFC, 0xD9, 0xDA, 0xDB, 0xDC },
    c = { 0xE7, 0xC7 }, n = { 0xF1, 0xD1 }, y = { 0xFD, 0xFF, 0xDD },
  }
  for letter, cps in pairs(map) do
    for _, cp in ipairs(cps) do LATIN[cp] = letter end
  end
end

-- lower case ASCII; accents off; any other byte becomes a space
function C.fold(s)
  s = tostring(s or '')
  local out, i, n = {}, 1, #s
  while i <= n do
    local b = s:byte(i)
    if b < 0x80 then
      out[#out + 1] = string.char(b):lower()
      i = i + 1
    else
      local cp
      local b2 = s:byte(i + 1)
      if (b == 0xC3 or b == 0xC2) and b2 and b2 >= 0x80 and b2 <= 0xBF then
        cp = (b == 0xC3) and (0xC0 + b2 - 0x80) or b2 -- C2 xx = U+0080..U+00BF, C3 xx = U+00C0..U+00FF
        i = i + 2
      elseif b >= 0xC4 and b <= 0xF4 and b2 and b2 >= 0x80 and b2 <= 0xBF then
        -- another UTF-8 sequence: skip its continuation bytes
        i = i + 1
        while i <= n and s:byte(i) >= 0x80 and s:byte(i) <= 0xBF do i = i + 1 end
      else
        cp = b -- a cp1252 byte
        i = i + 1
      end
      out[#out + 1] = (cp and LATIN[cp]) or ' '
    end
  end
  return table.concat(out)
end

-- ---------------------------------------------------------------- words
C.STOP = {}
for w in ([[a an the of to in on at by for from with and or is are was be it its this that these those my me i you your
  we our how do does did can could what which where when who why will would should get got have has there here any some
  about into than then so if not no up out more most very much many happen happens acontece
  o os as um uma uns umas de do da dos das no na nos nas em ao aos e ou que como onde quando quem qual quais por para pra
  com sem se eu meu minha meus minhas voce seu sua seus suas ele ela isso isto esse essa este esta ja mais muito muitos
  tem ter faco fazer consigo pegar posso pode]]):gmatch('%a+') do
  C.STOP[w] = true
end

-- plural and simple endings off, the same for the data and the query
function C.stem(w)
  local n = #w
  if n <= 3 then return w end
  if n > 4 and w:sub(-3) == 'oes' then return w:sub(1, -4) .. 'ao' end
  if n > 4 and w:sub(-3) == 'eis' then return w:sub(1, -4) .. 'el' end
  if n > 4 and w:sub(-3) == 'ies' then return w:sub(1, -4) .. 'y' end
  if w:sub(-2) == 'ns' then return w:sub(1, -3) .. 'm' end
  if w:sub(-1) == 's' and w:sub(-2) ~= 'ss' then return w:sub(1, -2) end
  return w
end

-- the stems of a text, in order, small words out (duplicates kept)
function C.tokens(s)
  local out = {}
  for w in C.fold(s):gmatch('[%w]+') do
    if not C.STOP[w] and (#w > 1 or w:match('%d')) then out[#out + 1] = C.stem(w) end
  end
  return out
end

-- ---------------------------------------------------------------- synonyms (en and pt; stems after fold)
C.SYNONYMS = {
  { 'level', 'nivel', 'lvl', 'leveling', 'upar', 'subir', 'evoluir' },
  { 'experience', 'experiencia', 'exp', 'xp' },
  { 'orb', 'orbe' },
  { 'gem', 'gema', 'socket', 'engaste' },
  { 'rift', 'fenda' },
  { 'dungeon', 'masmorra' },
  { 'boss', 'chefe', 'chefao' },
  { 'death', 'die', 'dead', 'morte', 'morrer', 'morri', 'morro' },
  { 'gold', 'ouro', 'money', 'dinheiro', 'coin', 'moeda' },
  { 'item', 'gear', 'equipment', 'equipamento' },
  { 'craft', 'crafting', 'upgrade', 'melhorar', 'forjar' },
  { 'salvage', 'reciclar', 'reciclagem' },
  { 'pet', 'mascote' },
  { 'guild', 'guilda', 'clan', 'cla' },
  { 'party', 'group', 'grupo', 'team', 'time' },
  { 'store', 'shop', 'loja' },
  { 'market', 'mercado', 'sell', 'vender', 'buy', 'comprar' },
  { 'tower', 'torre' },
  { 'pvp', 'arena', 'battleground' },
  { 'daily', 'diario', 'diaria' },
  { 'weekly', 'semanal' },
  { 'chest', 'bau' },
  { 'spell', 'magia', 'feitico' },
  { 'passive', 'passiva', 'tree', 'arvore' },
  { 'loot', 'saque', 'drop' },
  { 'faction', 'faccao' },
  { 'season', 'temporada' },
  { 'mount', 'montaria' },
  { 'outfit', 'traje', 'roupa' },
  { 'achievement', 'conquista' },
  { 'hunt', 'cacar', 'caca', 'cacada' },
  { 'monster', 'monstro', 'mob' },
  { 'potion', 'pocao' },
  { 'teleport', 'teletransporte', 'portal' },
  { 'town', 'city', 'cidade', 'temple', 'templo' },
  { 'invasion', 'invasao' },
  { 'siege', 'cerco' },
  { 'bounty', 'contract', 'contrato', 'task', 'tarefa' },
  { 'gamble', 'gambler', 'aposta', 'apostador' },
  { 'profession', 'profissao' },
  { 'charm', 'amuleto' },
  { 'bestiary', 'bestiario' },
  { 'hideout', 'esconderijo' },
  { 'storage', 'stash', 'depot', 'deposito', 'guardar' },
  { 'transmog', 'aparencia', 'look', 'visual' },
  { 'mentor', 'apprentice', 'aprendiz', 'veteran', 'veterano' },
}
local SYN = {}
for _, group in ipairs(C.SYNONYMS) do
  local stems = {}
  for i, w in ipairs(group) do stems[i] = C.stem(C.fold(w)) end
  for _, a in ipairs(stems) do
    SYN[a] = SYN[a] or {}
    for _, b in ipairs(stems) do
      if b ~= a then SYN[a][#SYN[a] + 1] = b end
    end
  end
end

-- {stem -> weight}: the word itself 1, its synonyms C.WEIGHT.synonym
function C.expand(stem)
  local out = { [stem] = 1 }
  for _, s in ipairs(SYN[stem] or {}) do
    if not out[s] then out[s] = C.WEIGHT.synonym end
  end
  return out
end

-- the words of a card row's heading (game_howitworks: "If you die", "What drops"...): a card with that row answers them
C.ROW_WORDS = {
  death = 'die dies death dead lose penalty morrer morte morri perder',
  drops = 'drops loot reward prize saque recompensa premio',
  often = 'often times limit cooldown wait vezes limite espera',
  levels = 'monster monstro',
}

-- a query with one of these words asks where something comes from: a card's "What drops" row then counts as much as a
-- title, and the Codex (which says what a thing does) counts less
C.SOURCE = {}
for w in ('get gets obtain farm earn source sources find ganhar obter conseguir farmar arrumar achar pegar vem'):gmatch('%a+') do
  C.SOURCE[w] = true
end
C.WEIGHT.source = 9
C.KIND_SOURCE_CODEX = 0.6

-- ---------------------------------------------------------------- the index
local function addSet(set, text)
  for _, t in ipairs(C.tokens(text)) do set[t] = true end
end

local function pick(t, lang)
  if type(t) ~= 'table' then return tostring(t or '') end
  local k = (type(lang) == 'string' and lang:lower():sub(1, 2) == 'pt') and 'pt' or 'en'
  return t[k] or t.en or ''
end
C.pick = pick

local function newDoc(kind, key, title)
  -- t: title stems, g: keywords / tab / menu / row headings, b: text, d: the "What drops" row of a card
  return { kind = kind, key = key, title = title, texts = {}, t = {}, g = {}, b = {}, d = {} }
end

-- doc.texts: {en, pt} pairs the snippet is cut from, in order of preference
local function addText(doc, pair)
  if type(pair) == 'string' then pair = { en = pair, pt = pair } end
  if not pair or (pair.en or '') == '' then return end
  doc.texts[#doc.texts + 1] = pair
  addSet(doc.b, pair.en)
  if pair.pt and pair.pt ~= pair.en then addSet(doc.b, pair.pt) end
end

local function addTitle(doc, pair)
  addSet(doc.t, pair.en)
  if pair.pt then addSet(doc.t, pair.pt) end
end

-- how = HowData, help = HelpSearchData, codex = CodexData (each may be nil)
function C.buildIndex(how, help, codex)
  local docs, cardDoc = {}, {}
  local meta = help and help.cards or {}
  for _, f in ipairs(how and how.features or {}) do
    local doc = newDoc('card', f.key, f.title)
    addTitle(doc, f.title)
    local m = meta[f.key] or {}
    doc.level, doc.menu = m.level, m.menu
    if m.words then
      addSet(doc.g, m.words.en)
      addSet(doc.g, m.words.pt)
    end
    if m.menu then addSet(doc.g, m.menu) end
    for _, r in ipairs(f.rows or {}) do
      addText(doc, r)
      if C.ROW_WORDS[r.id] then addSet(doc.g, C.ROW_WORDS[r.id]) end
      if r.id == 'drops' then
        addSet(doc.d, r.en)
        addSet(doc.d, r.pt)
      end
    end
    docs[#docs + 1] = doc
    cardDoc[f.key] = doc
  end
  for _, u in ipairs(help and help.unlocks or {}) do
    local doc = u.card and cardDoc[u.card]
    if doc then
      -- the unlock entry belongs to a card: its title, menu and lines make that card easier to find
      addSet(doc.g, u.title.en)
      addSet(doc.g, u.title.pt)
      addSet(doc.g, u.menu)
      addSet(doc.b, u.why.en)
      addSet(doc.b, u.why.pt)
      if not doc.level or u.level < doc.level then doc.level = u.level end
    else
      doc = newDoc('unlock', u.key, u.title)
      addTitle(doc, u.title)
      addSet(doc.g, u.menu)
      doc.level, doc.menu = u.level, u.menu
      addText(doc, u.why)
      docs[#docs + 1] = doc
    end
  end
  for _, tab in ipairs(codex and codex.tabs or {}) do
    for _, e in ipairs(tab.entries or {}) do
      local doc = newDoc('codex', e.id, { en = e.name, pt = e.name })
      doc.tab = tab.name
      addSet(doc.t, e.name)
      addSet(doc.g, tab.name)
      addText(doc, e.sub)
      local paragraphs = 0
      for _, sec in ipairs(e.sections or {}) do
        for _, p in ipairs(sec.p or {}) do
          if paragraphs < 4 then
            addText(doc, p)
            paragraphs = paragraphs + 1
          end
        end
      end
      docs[#docs + 1] = doc
    end
  end
  return { docs = docs, cards = cardDoc }
end

-- ---------------------------------------------------------------- search
local function match(set, stem)
  if set[stem] then return 1 end
  if #stem >= 3 then
    for t in pairs(set) do
      if #t > #stem and t:sub(1, #stem) == stem then return C.WEIGHT.prefix end
    end
  end
  return 0
end

-- true when the query asks where something comes from (C.SOURCE; read before the small words go)
function C.isSource(query)
  for w in C.fold(query):gmatch('%a+') do
    if C.SOURCE[w] then return true end
  end
  return false
end

-- the score of one doc for the query stems (source: C.isSource of the query)
function C.score(doc, words, source)
  local W = C.WEIGHT
  local total, hits, inTitle = 0, 0, 0
  for _, word in ipairs(words) do
    local best, titleHit = 0, false
    for stem, sw in pairs(C.expand(word)) do
      local t = match(doc.t, stem) * W.title * sw
      local g = match(doc.g, stem) * W.tag * sw
      local b = match(doc.b, stem) * W.body * sw
      local d = source and match(doc.d, stem) * W.source * sw or 0
      if t > 0 and sw == 1 then titleHit = true end
      best = math.max(best, t, g, b, d)
    end
    if best > 0 then hits = hits + 1 end
    if titleHit then inTitle = inTitle + 1 end
    total = total + best
  end
  if total <= 0 then return 0 end
  local cover = hits / #words
  total = total * (0.5 + 0.5 * cover)
  if inTitle == #words then total = total + W.allInTitle end
  local kind = C.KIND[doc.kind] or 1
  if source and doc.kind == 'codex' then kind = C.KIND_SOURCE_CODEX end
  return total * kind
end

local KIND_ORDER = { card = 1, unlock = 2, codex = 3 }

-- results {doc, score} best first; ties: cards first, then the lower level, then by title
function C.search(index, query, limit)
  local words = C.tokens(query)
  if #words == 0 or not index then return {}, words end
  local source = C.isSource(query)
  local out = {}
  for _, doc in ipairs(index.docs) do
    local s = C.score(doc, words, source)
    if s > 0 then out[#out + 1] = { doc = doc, score = s } end
  end
  table.sort(out, function(a, b)
    if math.abs(a.score - b.score) > 1e-9 then return a.score > b.score end
    local ka, kb = KIND_ORDER[a.doc.kind] or 9, KIND_ORDER[b.doc.kind] or 9
    if ka ~= kb then return ka < kb end
    local la, lb = a.doc.level or 0, b.doc.level or 0 -- what a new player can use first
    if la ~= lb then return la < lb end
    return (a.doc.title.en or '') < (b.doc.title.en or '')
  end)
  limit = limit or C.LIMIT
  while #out > limit do out[#out] = nil end
  return out, words
end

-- ---------------------------------------------------------------- snippet
-- cut at a space, at most max bytes, with "..." (never inside a UTF-8 letter: only at a space)
function C.shorten(s, max)
  s = tostring(s or ''):gsub('%s+', ' ')
  max = max or C.SNIPPET
  if #s <= max then return s end
  local cut = s:sub(1, max - 3)
  local at = cut:match('^.*() ')
  if at and at > 1 then cut = cut:sub(1, at - 1) end
  cut = cut:gsub('[%s,;:%.]+$', '')
  return cut .. '...'
end

-- the text of the doc that holds the most query words, in the language; the first text when none does
function C.snippet(doc, words, lang, max)
  local best, bestHits = nil, -1
  for _, pair in ipairs(doc.texts) do
    local text = pick(pair, lang)
    local set = {}
    for _, t in ipairs(C.tokens(text)) do set[t] = true end
    local hits = 0
    for _, w in ipairs(words or {}) do
      for stem in pairs(C.expand(w)) do
        if set[stem] then hits = hits + 1 break end
      end
    end
    if hits > bestHits then best, bestHits = text, hits end
  end
  return C.shorten(best or '', max)
end

-- the first steps (empty query): {doc, tip} in the order of HelpSearchData.steps, only cards that exist
function C.firstSteps(index, help)
  local out = {}
  for _, s in ipairs(help and help.steps or {}) do
    local doc = index and index.cards[s.card]
    if doc then out[#out + 1] = { doc = doc, tip = { en = s.en, pt = s.pt } } end
  end
  return out
end
